# Функция для создания уникального файла в новом временном каталоге
create_unique_file() {
    local temp_dir=$(mktemp -d)
    local file_name="${temp_dir}/file_$(date +%N)"
    touch "$file_name"
    echo "Created file: $file_name"
}

# Обёртка для ограничения количества итераций
wrapper() {
    local count=$1
    if (( count > 0 )); then
        base
        wrapper $((count - 1))
    fi
}

# Основная функция base
base() {
    create_unique_file
}

# Точка входа
wrapper 2

