        mkfifo "$fifo2" || { echo "Ошибка создания FIFO2"; exit 1; }

        # Удаление FIFO
        rm "$fifo1" || { echo "Ошибка удаления FIFO1"; exit 1; }
        rm "$fifo2" || { echo "Ошибка удаления FIFO2"; exit 1; }

        echo "FIFO1 и FIFO2 созданы и удалены"
    else
        # Рекурсивный вызов обёртки
        wrapper $((depth - 1))
    fi
}

