# Определение функции с циклом накопления FD, но не вызывай её
accumulate_fd() {
    local count=0
    while [ $count -lt 10 ]; do
        echo "FD $count"
        ((count++))
    done
}

# Производитель process substitution только печатает полное буквальное ядро
process_substitution() {
    accumulate_fd
}

# Source читает его в отдельном shell
source <(process_substitution)
